def get_Odd_Occurrence(arr, arr_size):
    """Write a python function to find the element occurring odd number of times.

    Consider the first ``arr_size`` elements of ``arr`` (the whole array
    when ``arr_size`` is None) and return the first element, in order of
    first appearance, that occurs an odd number of times. Return ``None``
    when no such element exists.
    """
    if arr_size is not None:
        elements = arr[:max(arr_size, 0)]
    else:
        elements = arr

    counts = {}
    for element in elements:
        counts[element] = counts.get(element, 0) + 1

    for element, count in counts.items():
        if count % 2 == 1:
            return element

    return None
